import {__testHooks} from '../../../automation/chatgpt.mjs';
process.on('message',async m=>{if(m?.operation!=='exercise')return;let cdp;try{const result=await __testHooks.launch(process.env.YM_FIXTURE_DIR);cdp=result.cdp;const ready=await __testHooks.waitHandoffComposerReady(cdp,4000);const account=await cdp.eval('localStorage.getItem("fixture-account")');await cdp.send('DOM.enable');const {root}=await cdp.send('DOM.getDocument');const {nodeId}=await cdp.send('DOM.querySelector',{nodeId:root.nodeId,selector:'#upload'});await cdp.send('DOM.setFileInputFiles',{nodeId,files:[m.file]});const uploaded=await cdp.eval('document.querySelector("#upload").files[0].name');const draft=await __testHooks.manualComposerText(cdp);process.send({fixtureResult:true,id:m.id,ok:true,ready,account,uploaded,draft,docked:result.docked,port:result.port})}catch(error){process.send({fixtureResult:true,id:m.id,ok:false,error:String(error.stack||error)})}finally{cdp?.close()}});
